function fieldControl(label,path,type='text',options={}){const base=options.doc?doc:doc.elements.find(e=>selected.has(e.id));const value=get(base,path);const data=options.doc?'data-we-doc-prop':'data-we-prop';const attr=`${data}="${path}"${!options.doc&&['x','y'].includes(path)&&automaticPosition(base)?' disabled':''}`;if(type==='select')return `<label>${label}<select ${attr}>${options.items.map(item=>{const [key,title]=Array.isArray(item)?item:[item,item];return `<option value="${esc(key)}" ${value===key?'selected':''}>${esc(title)}</option>`;}).join('')}</select></label>${help(path)}`;if(type==='checkbox')return `<label class="we-check"><input type="checkbox" ${attr} ${value?'checked':''}>${label}</label>${help(path)}`;if(type==='textarea')return `<label>${label}<textarea ${attr} rows="${options.rows||3}" spellcheck="false">${esc(value)}</textarea></label>${help(path)}`;return `<label>${label}<input ${attr} type="${type}" value="${esc(value)}" ${type==='number'?`step="${options.step||1}" min="${options.min??-16384}" max="${options.max??8192}"`:''} ${options.color?'list="wePaletteColors"':path==='style.fontFamily'?'list="weSystemFonts"':''}></label>${help(path)}`;}
